function AtlasHeroMotion() {
  const video = P.useRef(null);
  const [reduceMotion, setReduceMotion] = P.useState(
    () => window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
  const [playing, setPlaying] = P.useState(false);
  const [failed, setFailed] = P.useState(false);

  P.useEffect(() => {
    const preference = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => {
      setReduceMotion(preference.matches);
      setPlaying(false);
    };
    preference.addEventListener("change", onChange);
    return () => preference.removeEventListener("change", onChange);
  }, []);

  if (reduceMotion || failed) return null;

  return y.jsxs(y.Fragment, {
    children: [
      y.jsx("video", {
        ref: video,
        className: "atlas-hero-video",
        src: "./art/serpent-goddess-loop.mp4",
        autoPlay: true,
        loop: true,
        muted: true,
        playsInline: true,
        "aria-hidden": true,
        onPlaying: () => setPlaying(true),
        onPause: () => setPlaying(false),
        onError: () => setFailed(true)
      }),
      y.jsx("button", {
        type: "button",
        className: "atlas-motion-toggle",
        onClick: () => {
          const element = video.current;
          if (!element) return;
          if (element.paused) element.play().catch(() => setPlaying(false));
          else element.pause();
        },
        children: playing ? "Pause background" : "Play background"
      })
    ]
  });
}
